import { Card, Text, Avatar, Group, Textarea, ActionIcon, Loader, LoadingOverlay, Modal, ScrollArea, Box, Badge, Flex, CloseButton } from '@mantine/core';
import { IconEye, IconEyeCode, IconFileSearch, IconLiveView, IconMailSearch, IconMessage2Search, IconMessageSearch, IconSearch, IconSend, IconTrash, IconUser, IconView360 } from '@tabler/icons-react';
import { useFormStore } from '../../../../stores/formStore';
import { statuses } from '../../../../utils';
import { useAjax } from '../../../../hooks/useAjax';
import { useEffect, useState } from 'react';
import dayjs from 'dayjs';
import { parse } from 'path';
import { User } from '../../../../types/types';

type Email = {
  rendered: string,
  id: number,
  students: User[],
  audiences: string[],
}

export function EmailHistory() {
  const activityid = useFormStore((state) => state.id)
  const status = useFormStore((state) => state.status)
  const permissionsent = useFormStore((state) => state.permissionsent)
  const [emails, setEmails] = useState<any[]>([])
  const [fetchResponse, fetchError, fetchLoading, fetchAjax, setFetchedData] = useAjax(); // destructure state and fetch function
  const [selectedEmail, setSelectedEmail] = useState<Email|null>(null)

  useEffect(() => {
    if (activityid) {
      getEmailHistory()
    }
  }, [activityid]);

  const getEmailHistory = () => {
    console.log("getting email history")
    fetchAjax({
      query: {
        methodname: 'local_activities-get_emails',
        id: activityid,
      }
    })
  }
  useEffect(() => {
    if (fetchResponse && !fetchError) {
      setEmails(fetchResponse.data)
      console.log("fetched emails:", fetchResponse.data)
    }
  }, [fetchResponse]);

  const student = (data: User) => {
    return (
        <Badge key={data.un} variant='filled' pl={0} color="gray.2" size="lg" radius="xl" leftSection={
          <Avatar alt={data.fn + " " + data.ln} size={24} mr={5} src={'/local/activities/avatar.php?username=' + data.un} radius="xl"><IconUser /></Avatar>
        }>
          <Flex gap={4}>
            <Text className="normal-case font-normal text-black text-sm">{data.ln + ", " + data.fn}</Text>
          </Flex>
        </Badge>
    )
  }


  if (status < statuses.approved || !emails.length) {
    return null
  }

  return (
    <>
      <Card withBorder  mb="lg">
        <Card.Section className='border-b' inheritPadding py="sm">
          <span className="text-base">Email history</span>
        </Card.Section>
        <Card.Section withBorder pos="relative" className=''>
            <LoadingOverlay visible={fetchLoading} />

            { permissionsent &&
              <div className="px-4 py-2 border-b border-gray-200 bg-green-50">
                <Text className="text-sm">Permission requests have been sent.</Text>
              </div>
            }


            { !!emails.length &&
              <div className='flex gap-1 px-4 py-2'>
                  <div className='flex-1 font-semibold'>Date</div>
                  <div className='flex-1 font-semibold'>Sender</div>
                  <div className='font-semibold w-8'></div>
              </div>
            }
            {
              emails.map((email, i) => {
                return (
                  <div key={email.id} className='flex items-center gap-1 border-t px-4 py-2'>
                    <div className='flex-1'>{dayjs.unix(Number(email.timecreated)).format("DD MMM YY h:mma")}</div>
                    <div className='flex-1'>{email.sender.fn} {email.sender.ln}</div>
                    <div className='w-8 text-center'><ActionIcon onClick={() => setSelectedEmail(email as Email)} variant='subtle'><IconMailSearch className='size-5' /></ActionIcon></div>
                  </div>
                )
              })
            }
          </Card.Section>
      </Card>
      {selectedEmail &&
        <Modal
          opened={!!selectedEmail} 
          onClose={() => setSelectedEmail(null)} 
          title="Email" 
          size="xl" 
          styles={{
            header: {
              borderBottom: '0.0625rem solid #dee2e6',
            },
            title: {
              fontWeight: 600,
            }
          }}
          >
            <Box my="md">
              <Text fz="sm" mb={5} fw={500} c="#212529">Scope</Text>
              <ScrollArea h={selectedEmail.students.length > 12 ? 100 : 'auto'} type="auto">
                <Group gap="xs">
                  { selectedEmail.students.map(item => student(item)) }
                </Group>
              </ScrollArea>
            </Box>
            <Box>
              <Text fz="sm" mb={5} fw={500} c="#212529">Audiences</Text>
              <Group gap="5">
                {selectedEmail.audiences.map((item, index) => (
                  <span key={index} className="capitalize">
                    {item}{index < selectedEmail.audiences.length - 1 ? ', ' : ''}
                  </span>
                ))}
              </Group>
            </Box>
            <div className="rendered-email text-base py-4 border-t mt-4">
              <div dangerouslySetInnerHTML={ {__html: selectedEmail?.rendered || ''} }></div>
            </div>
        </Modal>
      }
    </>
  );
}